export const allTemplates = modules;
export const templates = Object.fromEntries(modules.map((m) => [m.name, m]));

export function getTemplate(name) {
  const t = templates[name];
  if (!t) throw new Error(`Unknown template: \"${name}\" (${modules.length} registered).`);
  return t;
}

let installed = false;
export function installTemplateStyles(doc = document) {
  if (installed) return;
  installed = true;
  const style = doc.createElement("style");
  style.id = "template-styles";
  style.textContent = modules.map((m) => m.css || "").join("\n\n");
  doc.head.appendChild(style);
}
